<?php
namespace Modules\BankingMicrofinance\Services;
use Carbon\Carbon;use Modules\BankingMicrofinance\Entities\InstallmentPenalty;use Modules\BankingMicrofinance\Entities\PenaltyRule;
class PenaltyService{
 public function calculateAmount(float $overdueAmount,int $overdueDays,PenaltyRule $rule): float{if($overdueDays <= (int)$rule->grace_days){return 0.0;}$days=max(0,$overdueDays-(int)$rule->grace_days);$amount=match($rule->calculation_type){'daily_percent'=>$overdueAmount*((float)$rule->amount_or_rate/100)*$days,'monthly_percent'=>$overdueAmount*((float)$rule->amount_or_rate/100)*max(1,ceil($days/30)),default=>(float)$rule->amount_or_rate};if($rule->maximum_penalty!==null){$amount=min($amount,(float)$rule->maximum_penalty);}return round($amount,4);}
 public function applyForInstallment($installment,?PenaltyRule $rule=null): ?InstallmentPenalty{$rule=$rule?:PenaltyRule::where('is_active',1)->first();if(!$rule||empty($installment->due_date)){return null;}$due=Carbon::parse($installment->due_date)->startOfDay();$today=Carbon::today();$days=$due->lt($today)?$due->diffInDays($today):0;$dueAmount=(float)($installment->amount??$installment->installment_amount??0);$paid=(float)($installment->paid_amount??0);$overdue=max(0,$dueAmount-$paid);$penalty=$this->calculateAmount($overdue,$days,$rule);if($penalty<=0){return null;}return InstallmentPenalty::updateOrCreate(['installment_id'=>$installment->id,'penalty_date'=>$today->toDateString()],['business_id'=>$installment->business_id??null,'loan_id'=>$installment->loan_id,'penalty_rule_id'=>$rule->id,'overdue_amount'=>$overdue,'overdue_days'=>$days,'penalty_amount'=>$penalty,'status'=>'unpaid']);}
}
